const icon = (name, cls = '') => `<svg viewBox="0 0 24 24" class="${cls}" aria-hidden="true">${icons[name] || icons.spark}</svg>`;
const e = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateFmt = (value, opts = {}) => { if (!value) return '—'; const d = new Date(value); return Number.isNaN(d.valueOf()) ? '—' : d.toLocaleString('pt-BR', { day:'2-digit', month:'short', hour:'2-digit', minute:'2-digit', ...opts }); };
const statusNames = { draft:'Rascunho', rendering:'Renderizando', ready:'Pronto', scheduled:'Agendado', publishing:'Publicando', published:'Publicado', failed:'Falha', queued:'Na fila', generating:'Gerando roteiro', completed:'Concluído', rendered:'Vídeo pronto', cancelled:'Cancelada', paused:'Pausado' };
const badge = status => `<span class="badge ${['published','completed','rendered'].includes(status) ? 'green' : ['rendering','publishing','generating'].includes(status) ? 'purple' : status === 'failed' ? 'red' : status === 'scheduled' ? 'blue' : ''}">${e(statusNames[status] || status)}</span>`;
const brand = () => `<a class="brand" href="#overview" aria-label="AUTOPOSTS início"><span class="brand-mark" aria-hidden="true">ϟ</span>AUTOPOSTS<small>BETA</small></a>`;
function toast(message, error = false) { const node = document.createElement('div'); node.className = `toast${error ? ' error' : ''}`; node.innerHTML = `${icon(error ? 'info' : 'check')}<span>${e(message)}</span>`; $('#toast-region').append(node); setTimeout(() => node.remove(), error ? 9000 : 5000); }
function apiError(detail) { if (Array.isArray(detail)) return detail.map(x => `${(x.loc || []).filter(y => y !== 'body').join('.')}: ${x.msg}`).join(' · '); return typeof detail === 'string' ? detail : 'Não foi possível concluir. Tente novamente.'; }
async function api(path, options = {}) { const method = options.method || 'GET'; const headers = { ...(options.headers || {}) }; let body = options.body; if (body && !(body instanceof FormData)) { headers['Content-Type'] = 'application/json'; body = JSON.stringify(body); } if (method !== 'GET' && state.session?.csrf_token) headers['X-CSRF-Token'] = state.session.csrf_token; let response; try { response = await fetch(path, { ...options, method, headers, body, credentials:'same-origin' }); } catch { throw new Error('Sem conexão com o servidor. Verifique a conexão e tente novamente.'); } const data = await response.json().catch(() => ({})); if (!response.ok) { if (response.status === 401 && state.session?.user) { state.session.user = null; closeModal(); render(); } throw new Error(apiError(data.detail)); } return data; }
async function refresh({quiet = false} = {}) { if (state.refreshBusy || !state.session?.user) return; state.refreshBusy = true; try { const [dashboard, campaigns, posts, assets, jobs, history] = await Promise.all([api('/api/dashboard'), api('/api/campaigns'), api('/api/posts'),api('/api/assets'),api('/api/jobs'),api('/api/billing/history')]); state.assets=assets.assets||[]; state.jobs=jobs.jobs||[]; state.billingHistory=history.events||[];state.pendingCheckout=history.pending_checkout; state.dashboard = dashboard; state.campaigns = campaigns.campaigns || []; state.capabilities = campaigns.capabilities || {}; state.posts = posts.posts || []; state.lastSync = new Date(); state.loadError = null; state.loading = false; render(); } catch (err) { state.loading = false; state.loadError = err.message; if (!quiet) { toast(err.message, true); render(); } } finally { state.refreshBusy = false; } }
function pageHeading(eyebrow, title, subtitle, actions = '') { return `<div class="page-heading"><div><div class="eyebrow">${e(eyebrow)}</div><h1>${e(title)}</h1><p>${e(subtitle)}</p></div>${actions ? `<div class="heading-actions">${actions}</div>` : ''}</div>`; }
const newCampaignButton = `<button class="btn btn-primary" data-action="new-campaign">${icon('plus')}Nova automação</button>`;
function shell() { const u = state.session.user; const nav = [['overview','grid','Visão geral'],['campaigns','bolt','Automações'],['videos','video','Meus vídeos'],['library','image','Biblioteca'],['schedules','calendar','Agendamentos'],['activity','activity','Atividade'],['settings','link','Conexões e planos'],['account','settings','Minha conta'],['help','info','Ajuda']]; const active = nav.find(n => n[0] === state.page) || nav[0]; const initial = (u.name || u.email || 'A').split(' ').map(s => s[0]).slice(0,2).join('').toUpperCase(); return `<div class="mobile-overlay" data-action="close-nav"></div><aside class="sidebar" aria-label="Menu principal">${brand()}<p class="nav-caption">SEU ESTÚDIO</p><nav class="nav">${nav.map(([id,ico,label]) => `<a href="#${id}" class="${state.page === id ? 'active' : ''}" ${state.page === id ? 'aria-current="page"' : ''}>${icon(ico)}${label}${id === 'campaigns' && state.campaigns.length ? `<span class="nav-count">${state.campaigns.length}</span>` : ''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="upgrade-card"><div class="mini-label">${icon('spark')} ${u.plan !== 'free' ? 'Sua assinatura' : 'Mais espaço para crescer'}</div><p>${u.plan !== 'free' ? 'Confira seu consumo e gerencie sua assinatura.' : 'Planos para vídeos e imagens, com limites claros.'}</p><button class="btn btn-secondary" data-action="${u.plan !== 'free' ? 'billing-portal' : 'open-plans'}">${u.plan !== 'free' ? 'Gerenciar assinatura' : 'Conhecer plano Pro'}${icon('arrowUp')}</button></div><div class="profile"><span class="avatar">${e(initial)}</span><div><p class="profile-name">${e(u.name || 'Meu estúdio')}</p><p class="profile-plan">Plano ${u.plan !== 'free' ? e(u.plan.toUpperCase()) : 'Demonstração'}</p></div><button class="icon-btn" data-action="logout" title="Sair da conta" aria-label="Sair da conta">${icon('logout')}</button></div></div></aside><div class="layout"><header class="topbar"><div class="topbar-left"><button class="icon-btn mobile-menu" data-action="open-nav" aria-label="Abrir menu">${icon('menu')}</button><div class="breadcrumb"><span>Seu estúdio</span>${icon('chevron')}<strong>${e(active[2])}</strong></div></div><div class="topbar-right"><span class="system-state"><span class="state-dot"></span>${state.campaigns.some(c=>c.enabled) ? 'Automação ativa' : 'Estúdio conectado'}</span><span class="topbar-separator"></span><span class="date-label">${new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'})}</span><button class="icon-btn" data-action="refresh" title="Atualizar painel" aria-label="Atualizar painel">${icon('refresh')}</button></div></header><main id="main-content" class="main-content" tabindex="-1">${state.loading ? loadingView() : state.loadError && !state.dashboard ? errorView() : views[state.page]?.() || overviewView()}<footer class="footer"><span>AUTOPOSTS · Menos tarefas. Mais presença.</span><span>${icon('shield')}Você mantém o controle da sua marca.</span></footer></main></div>`; }
function loadingView() { return `<div class="page-heading skeleton"><div><div class="eyebrow">SEU ESTÚDIO</div><h1>Carregando seu painel…</h1><p>Buscando suas automações e publicações.</p></div></div><div class="stats-grid skeleton">${[1,2,3,4].map(()=>'<div class="stat-card"><div class="stat-number">—</div><div class="stat-foot">Atualizando</div></div>').join('')}</div>`; }
function errorView() { return `<div class="panel empty-state"><div class="empty-icon">${icon('info')}</div><h3>Não conseguimos carregar seu estúdio</h3><p>${e(state.loadError)}</p><button class="btn btn-primary" data-action="refresh">Tentar novamente</button></div>`; }
function overviewView() { const stats = state.dashboard?.stats || {}; const campaigns = state.campaigns; const enabled = campaigns.filter(c=>c.enabled).length; const ready = state.posts.filter(p=>p.status === 'ready'&&p.kind!=='image').length; const name = (state.session.user.name || 'criador').split(' ')[0]; const statData = [['Automações ativas',enabled,'bolt','',`${campaigns.length} ${campaigns.length === 1 ? 'campanha criada' : 'campanhas criadas'}`],['Imagens criadas',stats.images || 0,'image','orange','Posts estáticos na sua biblioteca'],['Vídeos criados',stats.videos || 0,'video','blue',`${ready} ${ready === 1 ? 'pronto para publicar' : 'prontos para publicar'}`],['Na fila de publicação',stats.scheduled || 0,'calendar','orange','Horários definidos por você'],['Posts publicados',stats.published || 0,'check','green','Publicados pelo AUTOPOSTS']]; return `${pageHeading('SEU CONTEÚDO, SEM PAUSAS',`Olá, ${name}. 👋`,'Seu próximo conteúdo começa aqui. A rotina fica com a gente.',newCampaignButton)}${renderOAuthBanner()}<section class="hero"><div class="hero-copy"><div class="hero-tag">${icon('spark')} SUA MARCA NO PILOTO AUTOMÁTICO</div><h2>Você cuida do negócio.<br><span>A gente cuida do conteúdo.</span></h2><p>Defina o nicho e os horários. O AUTOPOSTS cria os vídeos e publica no Instagram, todos os dias.</p><button class="btn btn-primary btn-small" data-action="${campaigns.length ? 'go-campaigns' : 'new-campaign'}">${icon('bolt')}${campaigns.length ? 'Gerenciar minhas automações' : 'Criar minha primeira automação'}${icon('arrow')}</button></div><div class="orbital" aria-hidden="true"><span class="orbit"></span><span class="orbit"></span><span class="orbit"></span><span class="orbit-core">${icon('bolt')}</span><span class="orbit-node one">${icon('spark')}</span><span class="orbit-node two">${icon('video')}</span><span class="orbit-node three">${icon('instagram')}</span></div></section><section class="stats-grid" aria-label="Resumo do estúdio">${statData.map(([label,count,ico,color,foot]) => `<article class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon ${color}">${icon(ico)}</span></div><p class="stat-number">${count}</p><p class="stat-foot">${e(foot)}</p></article>`).join('')}</section>${usagePanel()}<div class="two-column"><section class="panel"><div class="panel-heading"><div><h2>Suas automações</h2><p>Uma configuração. Conteúdo em movimento.</p></div><a href="#campaigns" class="btn-link">Ver todas ${icon('chevron','inline-chevron')}</a></div>${campaigns.length ? `<div class="dashboard-campaigns">${campaigns.slice(0,3).map(dashboardCampaign).join('')}</div>` : `<div class="empty-state"><div class="empty-icon">${icon('bolt')}</div><h3>Seu conteúdo pode trabalhar por você</h3><p>Crie uma automação com a sua identidade. Escolha os temas e deixe a produção com a gente.</p><button class="btn btn-secondary btn-small" data-action="new-campaign">${icon('plus')}Configurar automação</button></div>`}</section><div>${setupChecklist()}<div class="note-card">${icon('info')}<p><strong>Você decide quando começar.</strong><br>Uma automação só publica depois que você conecta o Instagram e ativa a campanha.</p></div></div></div><div class="section-title"><div><h2>Do seu nicho ao próximo post</h2><p>O ciclo que mantém sua marca em movimento.</p></div><span class="badge">COMO FUNCIONA</span></div><div class="workflow-line">${[['spark','01','Ideias com a sua voz','Temas e roteiros alinhados ao nicho da sua marca.'],['video','02','Vídeos que ganham vida','Cenas em formato vertical, prontas para Reels.'],['calendar','03','O horário é seu','Frequência e horários no fuso da sua audiência.'],['instagram','04','Publicação automática','Seus vídeos chegam ao Instagram sem tarefas diárias.']].map(([ico,n,t,p])=>`<div class="workflow-step"><div class="step-top">${icon(ico)}<span>${n}</span></div><h3>${t}</h3><p>${p}</p></div>`).join('')}</div>${nextPostsPanel()}`; }
function dashboardCampaign(c) { return `<div class="dashboard-campaign-row"><span class="campaign-icon">${icon(c.mode === 'ai' ? 'spark' : 'bolt')}</span><div class="dashboard-campaign-copy"><strong>${e(c.name)}</strong><p>${e(c.times.join(' · '))} · ${e(c.timezone)}</p></div><span class="badge ${c.enabled ? 'green' : ''}">${c.enabled ? 'Ativa' : 'Pausada'}</span><button class="icon-btn" data-action="edit-campaign" data-id="${e(c.id)}" title="Editar automação" aria-label="Editar ${e(c.name)}">${icon('chevron')}</button></div>`; }
function setupChecklist() { const accounts = state.dashboard?.accounts || []; const steps = [{done:accounts.length>0,title:'Conecte seu Instagram',text:'Use uma conta profissional ou de criador.',action:'connect-instagram',cta:'Conectar conta'},{done:state.campaigns.length>0,title:'Dê a direção do conteúdo',text:'Conte sobre seu nicho, temas e estilo.',action:'new-campaign',cta:'Configurar agora'},{done:state.campaigns.some(c=>c.enabled),title:'Ative o piloto automático',text:'Escolha os horários e autorize a publicação.',action:'go-campaigns',cta:'Ver automações'}]; const count = steps.filter(s=>s.done).length; return `<section class="panel setup-panel"><div class="panel-heading"><h2>Seu estúdio, pronto para criar</h2><span class="label">${count} DE 3</span></div><div class="progress-track"><div style="width:${count/3*100}%"></div></div>${steps.map((s,i)=>`<div class="setup-item"><span class="step-marker ${s.done?'done':''}">${s.done?icon('check'):i+1}</span><div><h3>${s.title}</h3><p>${s.text}</p>${!s.done?`<button class="btn-link" data-action="${s.action}">${s.cta} →</button>`:''}</div></div>`).join('')}</section>`; }
function nextPostsPanel() { const posts = state.posts.filter(p=>['scheduled','publishing'].includes(p.status)).sort((a,b)=>String(a.scheduled_at).localeCompare(String(b.scheduled_at))); if (!posts.length) return ''; return `<div class="section-title"><h2>Próximas publicações</h2><a href="#activity" class="btn-link">Ver atividade</a></div><div class="panel table-wrap"><table><thead><tr><th>Vídeo</th><th>Publicação</th><th>Status</th></tr></thead><tbody>${posts.slice(0,5).map(p=>`<tr><td>${e(p.title)}</td><td>${dateFmt(p.scheduled_at)}</td><td>${badge(p.status)}</td></tr>`).join('')}</tbody></table></div>`; }
function campaignsView() { return `${pageHeading('CRIE UMA VEZ. PUBLIQUE SEMPRE.','Automações','A direção é sua. A criação e a publicação são automáticas.',newCampaignButton)}${!state.capabilities.public_url ? `<div class="info-note">${icon('info')} <span>Você já pode configurar campanhas e gerar vídeos de teste. A publicação automática fica disponível após conectar o Instagram e configurar o endereço público seguro do aplicativo.</span></div><div class="mt-20"></div>` : ''}${state.campaigns.length ? `<section class="campaign-grid">${state.campaigns.map(campaignCard).join('')}</section>` : `<section class="panel"><div class="empty-state"><div class="empty-icon">${icon('bolt')}</div><h3>Uma rotina de conteúdo começa com uma ideia</h3><p>Defina seu nicho, forneça conteúdos-base ou use IA e escolha os horários. Sua primeira automação está a poucos passos.</p>${newCampaignButton}</div></section>`}<div class="note-card">${icon('shield')}<p>A ativação autoriza criar e publicar os próximos vídeos sem revisão individual. Pause a campanha a qualquer momento. Uma publicação já em andamento pode ser concluída.</p></div>`; }
function campaignCard(c) { const account = (state.dashboard?.accounts || []).find(a=>a.id === c.account_id); return `<article class="campaign-card"><div class="campaign-top"><div class="campaign-title"><span class="campaign-icon">${icon(c.mode === 'ai'?'spark':'bolt')}</span><div><h3 title="${e(c.name)}">${e(c.name)}</h3><p>${e(c.niche)}</p></div></div><span class="badge ${c.enabled?'green':''}">${c.enabled?'● Ativa':'Pausada'}</span></div><div class="campaign-meta"><div>Criação<strong>${c.mode === 'ai'?'Roteiros com IA':'Conteúdos-base'}</strong></div><div>Conta<strong>${account ? '@'+e(account.platform_username) : 'Ainda não conectada'}</strong></div><div>Horários<strong>${e((c.times || []).join(' · '))} <span class="muted">${e(c.timezone?.split('/').pop()?.replaceAll('_',' ') || '')}</span></strong></div><div>Próxima execução<strong>${c.enabled ? dateFmt(c.next_run_at) : 'Aguardando ativação'}</strong></div></div>${c.last_error?`<p class="error-note">${e(c.last_error)}</p>`:''}<div class="campaign-bottom"><button class="btn btn-secondary btn-small" data-action="preview-campaign" data-id="${e(c.id)}" title="Gera um vídeo de teste sem publicar">${icon('eye')}Testar vídeo</button><button class="icon-btn" data-action="campaign-runs" data-id="${e(c.id)}" title="Ver execuções" aria-label="Ver execuções">${icon('activity')}</button><button class="icon-btn" data-action="edit-campaign" data-id="${e(c.id)}" title="Editar campanha" aria-label="Editar campanha">${icon('edit')}</button><button class="icon-btn" data-action="delete-campaign" data-id="${e(c.id)}" title="Excluir campanha" aria-label="Excluir campanha">${icon('trash')}</button><span class="spacer"></span><button class="btn ${c.enabled?'btn-secondary':'btn-primary'} btn-small" data-action="toggle-campaign" data-id="${e(c.id)}">${icon(c.enabled?'pause':'play')}${c.enabled?'Pausar':'Ativar'}</button></div></article>`; }
function videosView() { const posts=state.posts.filter(p=>(p.kind||'video')==='video');return `${pageHeading('CRIAÇÃO REAL, NO SEU ESTÚDIO','Meus vídeos','Reels verticais de até 60 segundos, com cenas, identidade visual e CTA.',`<button class="btn btn-primary" data-action="new-video">${icon('plus')}Criar vídeo</button>`)}${posts.length?`<div class="media-grid">${posts.map(videoCard).join('')}</div>`:emptyLibrary('Crie seu primeiro vídeo ou teste uma campanha.')}`; }
function videoCard(p) { const image=p.kind==='image';const busy=!!p.generation_status||['rendering','publishing'].includes(p.status);return `<article class="video-card"><div class="video-cover ${e(p.theme)}">${p.video_url?(image?`<img src="${e(p.video_url)}" alt="${e(p.title)}" loading="lazy" style="width:100%;height:100%;object-fit:contain">`:`<video src="${e(p.video_url)}" preload="none" controls playsinline aria-label="${e(p.title)}"></video>`):`<p class="scene-preview">${e(p.scenes?.[0]?.text||p.title)}</p>`}<span class="format-label">${image?'Imagem · 4:5':`9:16 · ${e(p.duration)}s`}</span>${busy?`<div class="rendering-indicator"><span class="loader"></span>${p.generation_status?'Gerando roteiro':'Processando'}</div>`:''}</div><div class="video-details"><div class="video-detail-top"><h3>${e(p.title)}</h3>${badge(p.generation_status||p.status)}</div><p>${dateFmt(p.created_at)}${p.scheduled_at?' · Publicação '+dateFmt(p.scheduled_at):''}</p>${p.media_deleted_at?'<p class="error-note">Arquivo removido pela política de retenção.</p>':''}${p.last_error?`<p class="error-note">${e(p.last_error)}</p>`:''}<div class="video-actions">${p.video_url?`<a class="btn btn-secondary btn-small" href="${e(p.video_url)}" download>${icon('download')}Baixar</a>`:''}${!busy&&['draft','failed'].includes(p.status)?`<button class="btn btn-primary btn-small" data-action="render-video" data-id="${e(p.id)}">Gerar ${image?'imagem':'vídeo'}</button>`:''}${!busy&&['draft','ready','failed'].includes(p.status)?`<button class="btn btn-secondary btn-small" data-action="edit-video" data-id="${e(p.id)}">Editar</button>`:''}${p.status==='ready'&&p.video_url?`<button class="btn btn-primary btn-small" data-action="schedule-video" data-id="${e(p.id)}">Agendar</button><button class="btn btn-secondary btn-small" data-action="publish-now" data-id="${e(p.id)}">Publicar agora</button>`:''}${p.status==='scheduled'?`<button class="btn btn-secondary btn-small" data-action="unschedule-video" data-id="${e(p.id)}">Desagendar</button>`:''}${!busy&&p.status!=='scheduled'?`<button class="icon-btn" data-action="delete-video" data-id="${e(p.id)}" aria-label="Excluir ${e(p.title)}">${icon('trash')}</button>`:''}</div></div></article>`;}
function activityView() { const posts = [...state.posts].sort((a,b)=>String(b.updated_at).localeCompare(String(a.updated_at))); return `${pageHeading('ACOMPANHE CADA ETAPA','Atividade','Do roteiro ao Instagram, saiba o que está acontecendo.',`<button class="btn btn-secondary" data-action="refresh">${icon('refresh')}Atualizar</button>`)}<section class="panel"><div class="panel-heading"><div><h2>Histórico de vídeos</h2><p>Dados reais das suas criações e publicações.</p></div><span class="label">${posts.length} ${posts.length===1?'VÍDEO':'VÍDEOS'}</span></div><div class="table-wrap"><table><thead><tr><th>Conteúdo</th><th>Criado em</th><th>Publicação</th><th>Status</th><th></th></tr></thead><tbody>${posts.length ? posts.map(p=>`<tr><td><strong>${e(p.title)}</strong>${p.last_error?`<p class="error-note">${e(p.last_error)}</p>`:''}</td><td class="muted">${dateFmt(p.created_at)}</td><td class="muted">${dateFmt(p.scheduled_at)}</td><td>${badge(p.status)}</td><td>${p.video_url?`<a class="icon-btn" href="${e(p.video_url)}" download title="Baixar vídeo" aria-label="Baixar vídeo">${icon('download')}</a>`:''}</td></tr>`).join(''):`<tr class="empty-row"><td colspan="5">Ainda não há atividade. Os vídeos aparecerão aqui conforme suas automações criarem conteúdo.</td></tr>`}</tbody></table></div></section>`; }
function settingsView() { const accounts=state.dashboard?.accounts||[];return `${pageHeading('CONEXÃO OFICIAL, CONTEÚDO AUTORIZADO','Conexões e planos','Sua senha do Instagram nunca é solicitada pelo AUTO POSTS.')}<section class="panel integration-card"><h2>Instagram profissional</h2><p>Conecte uma conta Business ou Creator pela API oficial da Meta. A disponibilidade para clientes depende das permissões e revisões do aplicativo.</p>${accounts.map(a=>`<div class="account-row"><div><strong>@${e(a.platform_username)}</strong><p>Autorização até ${dateFmt(a.expires_at)}</p></div><div class="heading-actions"><button class="btn btn-secondary btn-small" data-action="check-permissions" data-id="${e(a.id)}">Verificar permissões</button><button class="btn btn-secondary btn-small" data-action="disconnect-account" data-id="${e(a.id)}">Desconectar</button></div></div>`).join('')}<button class="btn btn-primary" data-action="connect-instagram">Conectar Instagram</button></section>${pricingView()}<section class="panel profile-panel"><h2>Histórico de cobrança</h2>${state.billingHistory.length?state.billingHistory.map(h=>`<div class="run-item"><span>${dateFmt(h.created_at)} · ${e(h.plan||'')} · ${e(h.event_type)}</span>${badge(h.status||'')}</div>`).join(''):'<p>Nenhum evento de cobrança confirmado.</p>'}</section>`;}
function renderOAuthBanner() { const params = new URLSearchParams(location.search); if (params.get('instagram') === 'connected') return '<div class="status-banner">Instagram conectado. Agora você pode escolher a conta na sua automação.</div>'; if (params.get('instagram') === 'error' || params.has('error')) return `<div class="error-note">Não foi possível concluir a conexão com o Instagram. Tente novamente em Conexões e plano.</div>`; return ''; }
const views = {overview:overviewView,campaigns:campaignsView,videos:videosView,images:imagesView,library:libraryView,schedules:schedulesView,activity:activityView,settings:settingsView,account:accountView,help:helpView,pricing:pricingView,terms:termsView,privacy:privacyView,login:authView,signup:authView};
function authView() { const register = state.authMode === 'register'; return `<main id="main-content" class="auth-page"><section class="auth-story">${brand()}<div class="eyebrow">SEU CONTEÚDO. NO PILOTO AUTOMÁTICO.</div><h1>Sua marca presente.<br><span>Todos os dias.</span></h1><p>Transforme sua rotina de conteúdo em uma automação. Das ideias aos Reels publicados, seu estúdio trabalha enquanto você cuida do negócio.</p><div class="auth-workflow"><span class="auth-node">${icon('spark')}Ideias</span>${icon('arrow')}<span class="auth-node">${icon('video')}Vídeos</span>${icon('arrow')}<span class="auth-node">${icon('instagram')}Publicações</span></div><div class="auth-foot">${icon('shield')}Você define a direção. A automação faz acontecer.</div></section><section class="auth-form-side"><div class="auth-form-wrap"><div class="auth-mobile-brand">${brand()}</div><div class="eyebrow">BEM-VINDO AO SEU NOVO ESTÚDIO</div><h2>${register?'Seu próximo passo<br>é automático.':'Bom ter você de volta.'}</h2><p>${register?'Crie sua conta e dê tempo ao que importa.':'Suas ideias e automações estão esperando por você.'}</p><div class="auth-tabs" role="tablist" aria-label="Acesso à conta"><button role="tab" aria-selected="${register}" class="${register?'active':''}" data-action="auth-register">Criar conta</button><button role="tab" aria-selected="${!register}" class="${!register?'active':''}" data-action="auth-login">Entrar</button></div><form id="auth-form" class="auth-form">${register?`<div class="field"><label for="auth-name">Como podemos te chamar?</label><input id="auth-name" name="name" placeholder="Seu nome" autocomplete="name" required minlength="2" maxlength="80"></div>`:''}<div class="field"><label for="auth-email">Seu e-mail</label><input type="email" id="auth-email" name="email" placeholder="voce@seunegocio.com.br" autocomplete="email" required maxlength="254"></div><div class="field"><label for="auth-password">Senha</label><input type="password" id="auth-password" name="password" placeholder="${register?'Pelo menos 10 caracteres':'Sua senha'}" autocomplete="${register?'new-password':'current-password'}" required minlength="${register?'10':'1'}" maxlength="128">${register?'<span class="field-help">Use uma senha única, com pelo menos 10 caracteres.</span>':''}</div><p class="form-error" role="alert"></p><button class="btn btn-primary" type="submit">${register?'Criar meu estúdio':'Entrar no meu estúdio'}${icon('arrow')}</button></form><p class="auth-legal">${register?'Escolha uma assinatura para automatizar. Starter tem teste de 7 dias, com e-mail confirmado e cartão no checkout.':'Seu acesso é seguro. Seus conteúdos continuam aqui.'}</p><p class="auth-legal"><button class="btn-link" data-action="forgot-password">Esqueci minha senha</button> · <a href="#terms">Termos</a> · <a href="#privacy">Privacidade</a></p><div class="auth-status">${icon('bolt')}Um nicho. Uma configuração. Mais presença.</div></div></section></main>`; }
function render() { app.innerHTML=state.session?.user?shell():(['terms','privacy','help','pricing'].includes(state.page)?publicShell(views[state.page]()):['login','signup'].includes(state.page)?(state.authMode==='forgot'||state.authMode==='reset'?recoveryView():authView()):landingView()); }
function showModal(title, subtitle, body, footer = '', formId = null) { modal.innerHTML = `${formId?`<form id="${formId}">`:''}<div class="modal-header"><div><h2 id="modal-title">${e(title)}</h2>${subtitle?`<p>${e(subtitle)}</p>`:''}</div><button type="button" class="icon-btn" data-action="close-modal" aria-label="Fechar janela">${icon('close')}</button></div><div class="modal-body">${body}<p class="form-error" role="alert"></p></div>${footer?`<div class="modal-footer">${footer}</div>`:''}${formId?'</form>':''}`; modal.setAttribute('aria-labelledby','modal-title'); if (!modal.open) modal.showModal(); }
function closeModal() { modal.close(); modal.innerHTML = ''; }
function formError(form, message) { const node = $('.form-error', form); if (node) { node.textContent = message; node.classList.add('visible'); } else toast(message,true); }
function accountOptions(selected = '', optional = true) { return `${optional?'<option value="">Conectar depois</option>':'<option value="">Selecione a conta</option>'}${(state.dashboard?.accounts || []).map(a=>`<option value="${e(a.id)}" ${a.id===selected?'selected':''}>@${e(a.platform_username)}</option>`).join('')}`; }
function campaignPayload(c) { return {kind:c.kind||'video',duration:c.duration||45,weekdays:c.weekdays||[0,1,2,3,4,5,6],company_name:c.company_name||'',objective:c.objective||'',brand_config:c.brand_config||{},name:c.name,niche:c.niche,audience:c.audience,tone:c.tone,cta:c.cta,topics:c.topics,mode:c.mode,account_id:c.account_id || null,timezone:c.timezone,times:c.times,enabled:!!c.enabled}; }
function campaignEditor(id = null) { const c = state.campaigns.find(c=>c.id===id) || {name:'',niche:'',audience:'',tone:'Educativo e próximo',cta:'',topics:[],mode:'templates',times:['09:00'],timezone:'America/Sao_Paulo',account_id:null,enabled:false}; const body = `<input type="hidden" name="id" value="${e(id || '')}">${campaignExtras(c)}<div class="form-grid"><div class="field full"><label for="campaign-name">Nome da automação</label><input id="campaign-name" name="name" value="${e(c.name)}" placeholder="Ex.: Dicas diárias da minha marca" minlength="2" maxlength="80" required></div><div class="field"><label for="campaign-niche">Seu nicho</label><input id="campaign-niche" name="niche" value="${e(c.niche)}" placeholder="Ex.: Nutrição e bem-estar" minlength="3" maxlength="160" required></div><div class="field"><label for="campaign-audience">Para quem você fala?</label><input id="campaign-audience" name="audience" value="${e(c.audience)}" placeholder="Ex.: Pessoas com rotina corrida" maxlength="200"></div><div class="field"><label for="campaign-tone">Tom de voz</label><select id="campaign-tone" name="tone">${[...new Set(['Educativo e próximo','Inspirador e acolhedor','Direto e profissional','Leve e descontraído',c.tone].filter(Boolean))].map(t=>`<option ${c.tone===t?'selected':''}>${e(t)}</option>`).join('')}</select></div><div class="field"><label for="campaign-cta">Chamada para ação <small>(opcional)</small></label><input id="campaign-cta" name="cta" value="${e(c.cta)}" placeholder="Ex.: Siga para mais dicas" maxlength="200"></div></div><hr class="form-divider"><h3 class="form-section-title">Como os roteiros serão criados?</h3><div class="mode-options"><label class="mode-option"><input type="radio" name="mode" value="templates" ${c.mode==='templates'?'checked':''}><strong>Conteúdos-base</strong><p>Transforma seus textos em vídeos automaticamente.</p></label><label class="mode-option"><input type="radio" name="mode" value="ai" ${c.mode==='ai'?'checked':''}><strong>Roteiros com IA</strong><p>Cria novos roteiros a partir do nicho e dos temas.</p></label></div><div class="field mt-20"><label for="campaign-topics" id="topics-label">${c.mode==='ai'?'Temas para a IA':'Conteúdos-base'}</label><textarea id="campaign-topics" name="topics" rows="5" placeholder="${c.mode==='ai'?'3 formas de organizar sua rotina\nPequenos hábitos para uma vida mais leve':'Escreva uma dica completa por linha.\nCada texto servirá de base para um vídeo.'}" ${c.mode==='templates'?'required':''} maxlength="15000">${e(c.topics.join('\n'))}</textarea><span class="field-help" id="topics-help">${c.mode==='ai'?'Um tema por linha (opcional). A IA cria o roteiro e a legenda.':'Até 30 textos, com até 1.000 caracteres por linha. A automação alterna entre seus conteúdos.'}</span></div><div class="info-note" id="ai-warning" ${c.mode!=='ai'||state.capabilities.ai?'hidden':''}>A geração com IA depende da chave do provedor configurada pelo administrador. Você pode usar conteúdos-base enquanto isso.</div><hr class="form-divider"><h3 class="form-section-title">Sua rotina de publicação</h3><div class="form-grid"><div class="field"><label for="campaign-account">Conta do Instagram</label><select id="campaign-account" name="account_id">${accountOptions(c.account_id)}</select></div><div class="field"><label for="campaign-timezone">Fuso horário</label><select id="campaign-timezone" name="timezone">${[...new Set(['America/Sao_Paulo','America/Manaus','America/Belem','America/Fortaleza','America/Recife','America/Bahia','America/Cuiaba','America/Rio_Branco','America/Noronha','Europe/Lisbon','UTC',c.timezone])].map(z=>`<option value="${e(z)}" ${c.timezone===z?'selected':''}>${e(z.replaceAll('_',' '))}</option>`).join('')}</select></div><div class="field full"><label>Horários diários <small>(até 3)</small></label><div class="field-row">${[0,1,2].map((_,i)=>`<input type="time" name="time_${i}" aria-label="Horário ${i+1}" value="${e(c.times[i] || '')}" ${i===0?'required':''}>`).join('')}</div><span class="field-help">A criação começa nesses horários; a publicação acontece após o vídeo ficar pronto.</span></div></div><div class="note-card">${icon('info')}<p>${id&&c.enabled?'Esta campanha está ativa. As alterações serão aplicadas às próximas execuções.':'Sua campanha será salva pausada. Você poderá testar um vídeo antes de ativar a publicação automática.'}</p></div>`; showModal(id?'Editar automação':'Sua próxima rotina, automática','Defina a direção. O AUTOPOSTS cuida dos próximos passos.',body,`<button type="button" class="btn btn-secondary" data-action="close-modal">Cancelar</button><button class="btn btn-primary" type="submit">${icon('check')}${id?'Salvar alterações':'Criar automação'}</button>`,'campaign-form'); }
function activateCampaign(c) { showModal('Ativar o piloto automático',c.name,`<div class="info-note">Esta automação criará vídeos ${c.times.length} ${c.times.length===1?'vez':'vezes'} por dia, nos horários ${e(c.times.join(', '))} (${e(c.timezone)}), e publicará na conta conectada.</div><div class="note-card">${icon('info')}<p>Os vídeos são criados e publicados <strong>sem revisão individual</strong>. Confira os temas e o tom de voz antes de ativar. Você pode pausar quando quiser.</p></div><input type="hidden" name="id" value="${e(c.id)}"><label class="consent"><input type="checkbox" name="consent" required><span>Autorizo a criação e a publicação automática dos vídeos desta campanha no meu Instagram.</span></label>`,`<button type="button" class="btn btn-secondary" data-action="close-modal">Agora não</button><button class="btn btn-primary" type="submit">${icon('play')}Ativar automação</button>`,'activate-form'); }
async function videoEditor(id = null, kind = 'video') { const p = state.posts.find(p=>p.id===id) || {title:'',caption:'',scenes:[{text:''},{text:''},{text:''}],duration:45,theme:'violet',kind,brand_config:{}}; try { state.assets = (await api('/api/assets')).assets || []; } catch { state.assets = []; } const body = `<input type="hidden" name="id" value="${e(id||'')}"><input type="hidden" name="kind" value="${e(p.kind||'video')}">${brandingFields(p.brand_config||{})}<div class="field"><label for="video-title">Título do vídeo</label><input name="title" id="video-title" value="${e(p.title)}" maxlength="120" placeholder="Ex.: 3 hábitos que mudam sua rotina" required></div><div class="field"><label for="video-caption">Legenda do Instagram</label><textarea name="caption" id="video-caption" rows="3" maxlength="2200" placeholder="Sua legenda e hashtags…">${e(p.caption)}</textarea></div><div class="form-grid"><div class="field" ${p.kind==='image'?'hidden':''}><label for="video-duration">Duração total</label><select id="video-duration" name="duration">${[...new Set([6,10,15,20,30,45,60,p.duration])].sort((a,b)=>a-b).map(d=>`<option value="${d}" ${p.duration===d?'selected':''}>${d} segundos</option>`).join('')}</select></div><div class="field"><label for="video-theme">Estilo visual</label><select id="video-theme" name="theme">${[['violet','Violeta · criativo'],['ocean','Oceano · sereno'],['ember','Âmbar · acolhedor']].map(([v,t])=>`<option value="${v}" ${p.theme===v?'selected':''}>${t}</option>`).join('')}</select></div></div><hr class="form-divider"><div class="section-title no-margin"><h3 class="form-section-title">Cenas do vídeo</h3><label class="upload-label">${icon('image')}Enviar imagem<input type="file" id="asset-upload" accept="image/jpeg,image/png,image/webp"></label></div><div id="scene-list">${p.scenes.map(sceneRow).join('')}</div><button type="button" class="btn btn-secondary btn-small" data-action="add-scene">${icon('plus')}Adicionar cena</button><p class="field-help mt-20">As imagens são opcionais. O vídeo usa cenas com texto, em formato vertical 1080 × 1920. Salvar não publica no Instagram.</p>`; showModal(id?'Editar publicação':p.kind==='image'?'Criar imagem':'Criar vídeo',p.kind==='image'?'Organize seus blocos de texto, cores e logo.':'Monte as cenas. Depois, gere o vídeo em formato Reels.',body,`<button type="button" class="btn btn-secondary" data-action="close-modal">Cancelar</button><button class="btn btn-primary" type="submit">${icon('check')}Salvar vídeo</button>`,'video-form'); }
function sceneRow(scene, i) { return `<div class="scene-row"><div class="scene-row-top"><span>CENA ${i+1}</span><button type="button" class="icon-btn" data-action="remove-scene" aria-label="Remover cena">${icon('close')}</button></div><div class="field"><label class="sr-only" for="scene-${i}">Texto da cena ${i+1}</label><textarea id="scene-${i}" class="scene-text" placeholder="Texto desta cena…" maxlength="420" required>${e(scene.text)}</textarea></div><div class="field no-margin"><label class="sr-only" for="scene-asset-${i}">Imagem da cena ${i+1}</label><select class="scene-asset" id="scene-asset-${i}"><option value="">Fundo do tema · sem imagem</option>${state.assets.map(a=>`<option value="${e(a.id)}" ${scene.asset_id===a.id?'selected':''}>${e(a.original_name)}</option>`).join('')}</select></div></div>`; }
function scheduleVideo(p) { const tomorrow = new Date(Date.now()+60*60*1000); const local = new Date(tomorrow.getTime()-tomorrow.getTimezoneOffset()*60000).toISOString().slice(0,16); showModal('Agendar publicação',p.title,`<input type="hidden" name="id" value="${e(p.id)}"><div class="field"><label for="schedule-account">Conta do Instagram</label><select name="account_id" id="schedule-account" required>${accountOptions(p.account_id,false)}</select></div><div class="field"><label for="schedule-at">Data e hora</label><input type="datetime-local" name="scheduled_at" id="schedule-at" value="${local}" required><span class="field-help">Horário do seu dispositivo: ${e(Intl.DateTimeFormat().resolvedOptions().timeZone)}.</span></div><div class="info-note">Ao agendar, você autoriza a publicação deste vídeo e da sua legenda na conta selecionada.</div>`,`<button type="button" class="btn btn-secondary" data-action="close-modal">Cancelar</button><button class="btn btn-primary" type="submit">${icon('calendar')}Agendar publicação</button>`,'schedule-form'); }
function confirmModal(title, description, action, id, danger = false, label = 'Confirmar') { showModal(title,'',`<p class="text-small muted">${e(description)}</p>`,`<button class="btn btn-secondary" type="button" data-action="close-modal">Cancelar</button><button class="btn ${danger?'btn-danger':'btn-primary'}" data-action="${action}" data-id="${e(id)}">${e(label)}</button>`); }
async function onSubmit(event) { event.preventDefault(); const form = event.target; if (!(form instanceof HTMLFormElement)) return; if (form.dataset.busy) return; const formId = form.getAttribute('id'); const data = new FormData(form); form.dataset.busy='true'; const buttons = $$('button[type="submit"]', form); buttons.forEach(b=>b.disabled=true); $('.form-error',form)?.classList.remove('visible'); try { if (formId === 'auth-form') { const body = {email:data.get('email'),password:data.get('password')}; if (state.authMode==='register') body.name=data.get('name'); const result = await api(`/api/auth/${state.authMode}`,{method:'POST',body}); state.session = await api('/api/session'); state.session.user = result.user || state.session.user; state.page='overview';location.hash='overview';state.loading=true;render();await refresh(); } else if (formId === 'campaign-form') { const id=data.get('id'); const existing=state.campaigns.find(c=>c.id===id); const body={kind:data.get('kind')||'video',duration:Number(data.get('duration')||45),weekdays:data.getAll('weekday').map(Number),company_name:data.get('company_name')||'',objective:data.get('objective')||'',brand_config:readBrand(data),name:data.get('name').trim(),niche:data.get('niche').trim(),audience:data.get('audience').trim(),tone:data.get('tone'),cta:data.get('cta').trim(),topics:data.get('topics').split('\n').map(t=>t.trim()).filter(Boolean),mode:data.get('mode'),account_id:data.get('account_id')||null,timezone:data.get('timezone'),times:[data.get('time_0'),data.get('time_1'),data.get('time_2')].filter(Boolean).sort(),enabled:existing?.enabled||false}; if(!body.weekdays.length)throw new Error('Escolha pelo menos um dia da semana.'); if (body.mode==='templates' && !body.topics.length) throw new Error('Adicione pelo menos um conteúdo-base.'); if(body.topics.length>30 || body.topics.some(t=>t.length>1000)) throw new Error('Use até 30 textos, com no máximo 1.000 caracteres por linha.'); await api(id?`/api/campaigns/${id}`:'/api/campaigns',{method:id?'PUT':'POST',body}); closeModal(); state.page='campaigns'; location.hash='campaigns'; await refresh(); toast(id?'Automação atualizada.':'Automação criada e pausada. Teste um vídeo antes de ativar.'); } else if (formId === 'activate-form') { if (!data.get('consent')) throw new Error('Confirme a autorização de publicação automática.'); const c=state.campaigns.find(c=>c.id===data.get('id')); await api(`/api/campaigns/${c.id}`,{method:'PUT',body:{...campaignPayload(c),enabled:true}}); closeModal(); await refresh(); toast('Piloto automático ativado. Sua campanha seguirá os horários definidos.'); } else if (formId === 'video-form') { const id=data.get('id'); const body={kind:data.get('kind')||'video',brand_config:readBrand(data),title:data.get('title').trim(),caption:data.get('caption'),duration:Number(data.get('duration')),theme:data.get('theme'),scenes:$$('.scene-row',form).map(row=>({text:$('.scene-text',row).value.trim(),asset_id:$('.scene-asset',row).value||null}))}; if (!body.scenes.length || body.scenes.some(s=>!s.text)) throw new Error('Preencha o texto de todas as cenas.'); await api(id?`/api/posts/${id}`:'/api/posts',{method:id?'PUT':'POST',body});closeModal();location.hash=body.kind==='image'?'library':'videos';state.page=body.kind==='image'?'library':'videos'; await refresh(); toast('Publicação salva. Clique em Gerar para produzir o arquivo.'); } else if (formId === 'schedule-form') { const when = new Date(data.get('scheduled_at')); if (!Number.isFinite(when.valueOf()) || when <= new Date()) throw new Error('Escolha uma data e hora no futuro.'); await api(`/api/posts/${data.get('id')}/schedule`,{method:'POST',body:{account_id:data.get('account_id'),scheduled_at:when.toISOString()}}); closeModal(); await refresh(); toast('Publicação agendada.'); } } catch (err) { formError(form,err.message); } finally { delete form.dataset.busy; buttons.forEach(b=>b.disabled=false); } }
async function onClick(event) { const target=event.target.closest('[data-action]'); if (!target || target.disabled || target.dataset.busy) return; const action=target.dataset.action; const id=target.dataset.id; if (target.type !== 'submit') event.preventDefault(); try { switch(action) {
case 'auth-register': state.authMode='register'; state.page='signup';location.hash='signup';render();break;
case 'auth-login': state.authMode='login';state.page='login';location.hash='login';render();break;
case 'close-modal': closeModal(); break;
case 'open-nav': $('.sidebar')?.classList.add('open'); $('.mobile-overlay')?.classList.add('open'); break;
case 'close-nav': $('.sidebar')?.classList.remove('open'); $('.mobile-overlay')?.classList.remove('open'); break;
case 'refresh': await refresh(); break;
case 'logout': await api('/api/auth/logout',{method:'POST'}); state.session=await api('/api/session'); state.dashboard=null; state.posts=[]; state.campaigns=[]; closeModal(); render(); break;
case 'new-campaign': campaignEditor(); break;
case 'edit-campaign': campaignEditor(id); break;
case 'go-campaigns': location.hash='campaigns'; break;
case 'open-plans': location.hash='settings'; break;
case 'toggle-campaign': {const c=state.campaigns.find(c=>c.id===id); if(c.enabled) {await api(`/api/campaigns/${id}`,{method:'PUT',body:{...campaignPayload(c),enabled:false}}); await refresh(); toast('Automação pausada. As publicações em espera foram interrompidas.');} else activateCampaign(c); break;}
case 'preview-campaign': confirmModal('Gerar um vídeo de teste?', 'O teste cria um vídeo privado e usa 1 vídeo da sua cota mensal. Ele não será publicado no Instagram.', 'confirm-preview-campaign', id, false, 'Gerar vídeo de teste'); break;
case 'confirm-preview-campaign': target.dataset.busy='true'; target.disabled=true; await api(`/api/campaigns/${id}/run`,{method:'POST'}); closeModal(); await refresh(); toast('Teste iniciado. O vídeo aparecerá em Meus vídeos, sem ser publicado.'); location.hash='videos'; break;
case 'campaign-runs': {const c=state.campaigns.find(c=>c.id===id); const result=await api(`/api/campaigns/${id}/runs`); showModal('Execuções da automação',c?.name||'',(result.runs||[]).length?result.runs.map(r=>`<div class="run-item"><div><p>${r.preview?'Vídeo de teste':'Execução automática'} · ${dateFmt(r.created_at)}</p><small>${r.error?e(r.error):r.post_id?'Vídeo disponível em Meus vídeos':'Aguardando criação'}</small></div>${badge(r.status)}</div>`).join(''):'<p class="text-small muted">Esta automação ainda não foi executada. Gere um vídeo de teste para começar.</p>',`<button class="btn btn-secondary" data-action="close-modal">Fechar</button>`); break;}
case 'delete-campaign': confirmModal('Excluir automação?','A campanha será removida e novas execuções serão interrompidas. Os vídeos já criados continuam no estúdio.','confirm-delete-campaign',id,true,'Excluir automação'); break;
case 'confirm-delete-campaign': await api(`/api/campaigns/${id}`,{method:'DELETE'}); closeModal(); await refresh(); toast('Automação excluída.'); break;
case 'connect-instagram': {const result=await api('/api/integrations/instagram/authorize'); if(!result.url) throw new Error('A conexão com o Instagram não está disponível.'); location.assign(result.url); break;}
case 'disconnect-account': confirmModal('Desconectar Instagram?','Novas publicações nessa conta precisarão de uma nova conexão. Pause as automações que usam esta conta antes de desconectar.','confirm-disconnect',id,true,'Desconectar'); break;
case 'confirm-disconnect': await api(`/api/accounts/${id}`,{method:'DELETE'}); closeModal(); await refresh(); toast('Conta desconectada.'); break;
case 'checkout': {if(!state.session?.user){state.authMode='register';state.page='signup';location.hash='signup';render();break;} const result=await api('/api/billing/checkout',{method:'POST',body:{plan:target.dataset.plan||'pro'}}); if(result.url) location.assign(result.url); else throw new Error('Checkout indisponível.'); break;}
case 'billing-portal': {const result=await api('/api/billing/portal',{method:'POST'}); if(result.url) location.assign(result.url); else throw new Error('Portal de assinatura indisponível.'); break;}
case 'new-video': await videoEditor(); break;
case 'edit-video': await videoEditor(id); break;
case 'add-scene': {const list=$('#scene-list'); if($$('.scene-row',list).length>=6) throw new Error('Um vídeo pode ter até 6 cenas.'); list.insertAdjacentHTML('beforeend',sceneRow({text:''},$$('.scene-row',list).length)); break;}
case 'remove-scene': {if($$('.scene-row',modal).length<=1) throw new Error('O vídeo precisa de pelo menos uma cena.'); target.closest('.scene-row').remove(); $$('.scene-row-top span',modal).forEach((n,i)=>n.textContent=`CENA ${i+1}`); break;}
case 'render-video': if(state.posts.find(p=>p.id===id)?.render_count>0&&state.posts.find(p=>p.id===id)?.status!=='failed'){confirmModal('Gerar novamente?','Esta nova geração consome mais uma unidade da sua cota.','confirm-render-again',id,false,'Confirmar geração');break;} await api(`/api/posts/${id}/render`,{method:'POST'}); await refresh(); toast('Renderização iniciada. Você pode continuar usando o estúdio.'); break;
case 'schedule-video': scheduleVideo(state.posts.find(p=>p.id===id)); break;
case 'unschedule-video': await api(`/api/posts/${id}/unschedule`,{method:'POST'}); await refresh(); toast('Agendamento cancelado. O vídeo continua disponível.'); break;
case 'delete-video': confirmModal('Excluir vídeo?','O vídeo e seu arquivo serão removidos. Esta ação não remove publicações que já estão no Instagram.','confirm-delete-video',id,true,'Excluir vídeo'); break;
case 'confirm-delete-video': await api(`/api/posts/${id}`,{method:'DELETE'}); closeModal(); await refresh(); toast('Vídeo excluído.'); break;
} } catch(err) { if(modal.open) {const form=$('form',modal); if(form) formError(form,err.message); else toast(err.message,true);} else toast(err.message,true); } finally { delete target.dataset.busy; target.disabled=false; } }
document.addEventListener('click',onClick);
document.addEventListener('submit',onSubmit);
document.addEventListener('change',async event=>{ if(event.target.name==='mode') {const ai=event.target.value==='ai'; $('#campaign-topics').required=!ai; $('#topics-label').textContent=ai?'Temas para a IA':'Conteúdos-base'; $('#topics-help').textContent=ai?'Um tema por linha (opcional). A IA cria o roteiro e a legenda.':'Até 30 textos, com até 1.000 caracteres por linha. A automação alterna entre seus conteúdos.'; $('#ai-warning').hidden=!ai||state.capabilities.ai; } if(event.target.id==='asset-upload') {const file=event.target.files[0]; if(!file)return; if(file.size>10*1024*1024){toast('A imagem deve ter até 10 MB.',true);return;} const data=new FormData();data.append('file',file);try{const result=await api('/api/assets',{method:'POST',body:data});state.assets.push(result.asset);$$('.scene-asset',modal).forEach(select=>{const option=document.createElement('option');option.value=result.asset.id;option.textContent=result.asset.original_name;select.append(option);});toast('Imagem enviada. Selecione-a na cena desejada.');}catch(err){toast(err.message,true);} event.target.value=''; }});
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{state.page=location.hash.slice(1)||'overview'; if(!views[state.page])state.page='overview';render();window.scrollTo({top:0,behavior:'instant'});});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.session?.user)refresh({quiet:true});});
async function boot(){state.page=location.hash.slice(1)||'overview';if(!views[state.page])state.page='overview';try{const params=new URLSearchParams(location.search);state.resetToken=params.get('reset');const verification=params.get('verify');if(state.resetToken||verification){history.replaceState(null,'',location.pathname+'#login');state.page='login';if(state.resetToken)state.authMode='reset';} state.session=await api('/api/session');const [catalog,config]=await Promise.all([api('/api/plans'),api('/api/public/config')]);state.plans=catalog.plans||[];state.publicConfig=config;if(verification){try{await api('/api/auth/verify-email',{method:'POST',body:{token:verification}});toast('E-mail confirmado.');state.session=await api('/api/session');}catch(err){toast(err.message,true);}}render();if(state.session.user)await refresh();}catch(err){app.innerHTML=`<main id="main-content" class="boot-state"><div><h1>Seu estúdio está temporariamente indisponível</h1><p class="muted">${e(err.message)}</p><button class="btn btn-primary mt-20" data-action="refresh-page">Recarregar</button></div></main>`;document.querySelector('[data-action="refresh-page"]').addEventListener('click',()=>location.reload());}}
await boot();
setInterval(()=>{if(state.session?.user&&!document.hidden&&!modal.open&&!state.refreshBusy&&!$$('video').some(v=>!v.paused)){ const active=state.posts.some(p=>p.generation_status||['rendering','publishing'].includes(p.status));if(active||state.campaigns.some(c=>c.enabled)||!state.lastSync||Date.now()-state.lastSync>25000)refresh({quiet:true});}},5000);

// SaaS account, library and commercial flows extend the existing studio UI.
function publicShell(content){return `<main id="main-content" class="public-page"><header class="public-header">${brand()}<nav><a href="#pricing">Planos</a><a href="#help">Ajuda</a><button class="btn btn-secondary btn-small" data-action="auth-login">Entrar</button><button class="btn btn-primary btn-small" data-action="auth-register">Criar conta</button></nav></header>${content}<footer class="footer"><a href="#terms">Termos de uso</a><a href="#privacy">Privacidade</a><a href="#help">Ajuda</a></footer></main>`;}
function landingView(){return publicShell(`<section class="hero landing-hero"><div class="hero-copy"><div class="eyebrow">CONTEÚDO COM A SUA IDENTIDADE</div><h1>Sua marca em movimento.<br><span>No piloto automático.</span></h1><p>Configure sua campanha. O AUTO POSTS cria vídeos e imagens, agenda e publica no Instagram profissional depois da sua autorização.</p><div class="heading-actions"><button class="btn btn-primary" data-action="auth-register">Criar meu estúdio ${icon('arrow')}</button><a href="#pricing" class="btn btn-secondary">Conhecer planos</a></div><p class="field-help">Templates sem IA paga. Geração com IA é opcional. O teste Starter depende de e-mail confirmado e cartão no checkout.</p></div><div class="orbital" aria-hidden="true"><span class="orbit"></span><span class="orbit"></span><span class="orbit-core">${icon('bolt')}</span><span class="orbit-node one">${icon('image')}</span><span class="orbit-node two">${icon('video')}</span><span class="orbit-node three">${icon('instagram')}</span></div></section><div class="workflow-line">${[['01','Dê a direção','Nicho, público, temas e identidade visual.'],['02','Crie sua rotina','Dias, horários, duração e tipo de conteúdo.'],['03','Conecte com segurança','Instagram profissional pela API oficial.'],['04','Ative a campanha','Criação e publicação sem aprovar cada post.']].map(([n,t,d])=>`<article class="workflow-step"><span class="eyebrow">${n}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div>${pricingView()}`);}
function pricingView(){const u=state.session?.user;const usage=state.dashboard?.usage;return `${pageHeading('LIMITES CLAROS. SEM PLANO ILIMITADO.','Planos para o seu ritmo','Assinaturas mensais. Confirmações de pagamento dependem do provedor, nunca da página de sucesso.')}${state.pendingCheckout?`<div class="info-note"><span>Checkout pendente: ${e(state.pendingCheckout.plan)}</span><a class="btn btn-secondary btn-small" href="${e(state.pendingCheckout.checkout_url||'#settings')}">Continuar</a><button class="btn btn-secondary btn-small" data-action="cancel-checkout">Cancelar checkout pendente</button></div>`:''}<div class="pricing-grid">${state.plans.map(p=>`<article class="panel price-card"><span class="badge ${u?.plan===p.id?'green':''}">${u?.plan===p.id?'SEU PLANO':e(p.name)}</span><h2>${e(p.name)}</h2><p class="price">${(p.price_cents/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}<small>/mês</small></p><ul class="feature-list"><li>${icon('video')}${p.videos} vídeos por período</li><li>${icon('image')}${p.images} imagens por período</li><li>${icon('calendar')}Agendamento e automação</li><li>${icon('shield')}Conta e biblioteca privadas</li></ul>${p.trial_days?`<p class="field-help">${p.trial_days} dias de teste. Uma vez por e-mail confirmado. Cartão exigido no checkout.</p>`:''}<button class="btn btn-primary" data-action="${u?.plan&&u.plan!=='free'?'billing-portal':'checkout'}" data-plan="${e(p.id)}">${u?.plan&&u.plan!=='free'?'Gerenciar assinatura':'Escolher '+e(p.name)}</button></article>`).join('')}</div>${usage?`<section class="panel profile-panel"><h3>Seu consumo atual</h3><p>Vídeos: ${e(usage.videos?.used??usage.used)} / ${e(usage.videos?.limit??usage.limit)} · Imagens: ${e(usage.images?.used??0)} / ${e(usage.images?.limit??0)}</p><p>Status: ${e(usage.status)}${usage.renews_at?' · Período até '+dateFmt(usage.renews_at):''}</p><p class="field-help">Em desenvolvimento, a demonstração local é limitada. Publicação comercial exige assinatura ativa. Cancele ou altere o plano pelo portal seguro.</p></section>`:''}`;}
function emptyLibrary(message){return `<section class="panel empty-state"><div class="empty-icon">${icon('image')}</div><h3>Seu conteúdo começa aqui</h3><p>${e(message)}</p></section>`;}
function imagesView(){return `${pageHeading('POSTS ESTÁTICOS COM A SUA MARCA','Minhas imagens','Templates em JPEG 1080×1350, com cores, logo e chamada para ação.',`<button class="btn btn-primary" data-action="new-image">${icon('plus')}Criar imagem</button>`)}<div class="media-grid">${state.posts.filter(p=>p.kind==='image').map(videoCard).join('')}</div>`;}
function libraryView(){return `${pageHeading('VÍDEOS, IMAGENS E MATERIAIS DA MARCA','Biblioteca','Arquivos de cada cliente permanecem separados e privados.',`<button class="btn btn-primary" data-action="new-image">Criar imagem</button><button class="btn btn-secondary" data-action="new-video">Criar vídeo</button>`)}<div class="info-note">Arquivos podem ser removidos após ${e(state.session?.retention_days||10)} dias de inatividade. Mídias de publicações pendentes são protegidas; campanhas e cobranças permanecem.</div><div class="section-title"><h2>Publicações</h2></div>${state.posts.length?`<div class="media-grid">${state.posts.map(videoCard).join('')}</div>`:emptyLibrary('Crie um vídeo ou uma imagem para preencher sua biblioteca.')}<div class="section-title"><h2>Imagens e logos enviados</h2><label class="btn btn-secondary upload-label">Enviar imagem<input type="file" id="library-upload" accept="image/jpeg,image/png,image/webp"></label></div><div class="asset-grid">${state.assets.map(a=>`<article class="panel asset-card"><img src="${e(a.url)}" alt="${e(a.original_name)}" loading="lazy"><h3>${e(a.original_name)}</h3><p>${Math.round(a.size/1024)} KB</p><div class="heading-actions"><a class="btn btn-secondary btn-small" href="${e(a.url)}" download>Baixar</a><button class="btn btn-secondary btn-small" data-action="delete-asset" data-id="${e(a.id)}">Excluir</button></div></article>`).join('')}</div>`;}
function schedulesView(){const list=state.posts.filter(p=>['scheduled','publishing'].includes(p.status)).sort((a,b)=>String(a.scheduled_at).localeCompare(String(b.scheduled_at)));return `${pageHeading('SEU CALENDÁRIO DE CONTEÚDO','Agendamentos','Pause campanhas ou cancele publicações que ainda aguardam envio.')}<div class="media-grid">${list.map(videoCard).join('')}</div>${!list.length?emptyLibrary('Nenhuma publicação agendada.') :''}`;}
function accountView(){const u=state.session.user;return `${pageHeading('CONTROLE DA CONTA E DOS DADOS','Minha conta','Mantenha seu perfil e seu acesso atualizados.')}<div class="settings-grid"><section class="panel profile-panel"><h2>Perfil</h2><form id="profile-form"><div class="field"><label for="profile-name">Nome</label><input id="profile-name" name="name" value="${e(u.name)}" minlength="2" maxlength="80" required></div><p>${e(u.email)} · ${u.email_verified?'Confirmado':'Não confirmado'}</p>${!u.email_verified?'<button class="btn btn-secondary" type="button" data-action="verify-email">Enviar confirmação de e-mail</button>':''}<p class="form-error" role="alert"></p><button type="submit" class="btn btn-primary mt-20">Salvar perfil</button></form></section><section class="panel profile-panel"><h2>Alterar senha</h2><form id="password-form"><div class="field"><label>Senha atual<input name="current_password" type="password" autocomplete="current-password" required maxlength="128"></label></div><div class="field"><label>Nova senha<input name="password" type="password" autocomplete="new-password" minlength="10" maxlength="128" required></label></div><p class="form-error" role="alert"></p><button type="submit" class="btn btn-primary">Alterar e sair dos dispositivos</button></form></section></div><section class="panel profile-panel"><h2>Seus arquivos e sua conta</h2><p>A mídia pode ser excluída após ${e(state.session.retention_days||10)} dias sem acesso. Conteúdo já publicado no Instagram não é removido por esta política.</p><p>A exclusão da conta bloqueia o acesso, cancela a assinatura quando aplicável e solicita a limpeza dos arquivos. A conclusão depende da confirmação do armazenamento. Registros legais de cobrança podem permanecer.</p><button class="btn btn-danger" data-action="delete-account">Solicitar exclusão da conta</button></section>`;}
function helpView(){return `${pageHeading('DO PRIMEIRO ACESSO À ROTINA AUTOMÁTICA','Ajuda','Uma configuração inicial. Acompanhamento sempre disponível.')}<section class="panel profile-panel"><h2>Como começar</h2><ol class="help-list"><li>Crie uma conta, confirme seu e-mail e escolha um plano.</li><li>Conecte uma conta profissional do Instagram pela tela Conexões.</li><li>Crie uma campanha com nicho, temas, identidade visual, dias e horários.</li><li>Gere uma prévia. Ela consome cota, mas não publica.</li><li>Ative a campanha e confirme a autorização. As próximas execuções criam e publicam automaticamente.</li></ol><h2>Quando ocorre uma falha?</h2><p>Confira Atividade e Biblioteca. Falhas temporárias de armazenamento têm tentativas limitadas. Envio de publicação não confirmado exige conferir o Instagram antes de repetir, para evitar duplicação.</p><h2>Retenção</h2><p>Arquivos podem ser removidos após ${e(state.publicConfig.retention_days||10)} dias de inatividade, preservando mídias pendentes, campanhas e cobranças.</p><h2>Suporte</h2><p>${state.publicConfig.contact?e(state.publicConfig.contact):'O operador ainda precisa configurar o contato de suporte.'}</p><a href="#terms">Termos de uso</a> · <a href="#privacy">Privacidade</a></section>`;}
function termsView(){return `${pageHeading('TRANSPARÊNCIA PARA USAR O SERVIÇO','Termos de uso','Revise as condições antes de ativar sua rotina de conteúdo.')}<article class="panel profile-panel prose"><p>Operador: ${e(state.publicConfig.operator||'identificação pendente de configuração')}. Contato: ${e(state.publicConfig.contact||'pendente')}.</p>${!state.publicConfig.operator||!state.publicConfig.contact?'<div class="error-note">Documento pendente de identificação e revisão pelo operador. O serviço não deve ser oferecido publicamente como pronto antes dessa configuração.</div>':''}<h2>Serviço e autorização</h2><p>O AUTO POSTS cria vídeos e imagens a partir das informações do cliente, com IA opcional. Ativar uma campanha autoriza as próximas gerações e publicações sem revisão individual. O cliente é responsável por fornecer informações corretas, possuir direitos sobre os materiais e autorizar a conta profissional conectada.</p><h2>Assinaturas e limites</h2><p>Os valores e cotas aparecem na página de planos e no checkout. O Starter pode oferecer 7 dias de teste uma vez por e-mail confirmado, com cartão. Renovação, mudança de plano e cancelamento são administrados no portal de cobrança. O acesso depende da confirmação do provedor e está sujeito às cotas; não existe plano ilimitado.</p><h2>Disponibilidade</h2><p>Meta, armazenamento, IA e hospedagem podem impor limites ou interrupções. Uma publicação já enviada pode terminar após uma pausa. Falhas ambíguas são sinalizadas para conferência. Não há garantia de alcance, engajamento ou resultados comerciais.</p><h2>Arquivos e encerramento</h2><p>Mídia pode ser removida após ${e(state.publicConfig.retention_days||10)} dias de inatividade. Mídia pendente é preservada. A exclusão da conta solicita a limpeza e pode manter registros de cobrança legalmente necessários. O operador deve completar as condições legais aplicáveis antes do lançamento.</p></article>`;}
function privacyView(){return `${pageHeading('SEUS DADOS, COM PROPÓSITO','Política de privacidade','Informações sobre o tratamento dos seus dados.')}<article class="panel profile-panel prose"><p>Operador: ${e(state.publicConfig.operator||'identificação pendente')}. Contato: ${e(state.publicConfig.contact||'pendente')}.</p><h2>Dados tratados</h2><p>Nome, e-mail, senha protegida por hash, sessões, campanhas, materiais enviados, vídeos e imagens gerados, horários, histórico de execução e dados de assinatura são usados para prestar o serviço. Tokens da Meta são criptografados no servidor; sua senha do Instagram não é solicitada.</p><h2>Fornecedores</h2><p>O armazenamento privado usa Backblaze B2 quando configurado. A publicação usa a Meta. Pagamentos podem ser processados pelo Stripe, sem armazenar cartões no aplicativo. O modo IA envia o briefing ao provedor configurado, sendo opcional. O operador deve informar o fornecedor de hospedagem, região e demais tratamentos aplicáveis na documentação final.</p><h2>Cookies e retenção</h2><p>Cookies são usados para sessão e proteção CSRF. Arquivos podem ser removidos após ${e(state.publicConfig.retention_days||10)} dias de inatividade, exceto os necessários a trabalhos pendentes. Campanhas e registros de cobrança não são removidos por essa limpeza. A política de backups e retenção legal deve ser definida pelo operador.</p><h2>Direitos e exclusão</h2><p>Você pode alterar seu perfil, desconectar o Instagram ou solicitar exclusão da conta em Minha conta. Solicitações adicionais devem ser encaminhadas ao contato do operador. Identificação do controlador, bases legais, prazos legais e condições internacionais precisam de revisão antes da oferta pública.</p></article>`;}
function brandingFields(b={}){return `<details class="brand-details"><summary>Identidade visual e template</summary><div class="form-grid mt-20"><div class="field"><label>Nome da empresa<input name="company_name" value="${e(b.company_name||'')}" maxlength="80"></label></div><div class="field"><label>Cor principal<input type="color" name="primary_color" value="${e(/^#[a-f0-9]{6}$/i.test(b.primary_color||'')?b.primary_color:'#ab83ff')}"></label></div><div class="field"><label>Logo<select name="logo_asset_id"><option value="">Sem logo</option>${state.assets.map(a=>`<option value="${e(a.id)}" ${b.logo_asset_id===a.id?'selected':''}>${e(a.original_name)}</option>`).join('')}</select></label></div><div class="field"><label>Template<select name="style">${[['card','Editorial'],['quote','Citação'],['tips','Lista de dicas']].map(([v,t])=>`<option value="${v}" ${b.style===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="field full"><label>Chamada visual<input name="brand_cta" value="${e(b.cta||'')}" maxlength="200"></label></div></div></details>`;}
function readBrand(data){return {company_name:String(data.get('company_name')||''),primary_color:String(data.get('primary_color')||'#ab83ff'),logo_asset_id:data.get('logo_asset_id')||null,style:data.get('style')||'card',cta:String(data.get('brand_cta')||''),motion:true};}
function campaignExtras(c){return `<div class="form-grid"><div class="field"><label>Tipo de conteúdo<select name="kind"><option value="video" ${c.kind!=='image'?'selected':''}>Vídeo / Reels</option><option value="image" ${c.kind==='image'?'selected':''}>Imagem estática</option></select></label></div><div class="field"><label>Duração do vídeo<select name="duration">${[15,24,30,45,60].map(d=>`<option value="${d}" ${(c.duration||45)===d?'selected':''}>${d} segundos</option>`).join('')}</select></label></div><div class="field full"><label>Objetivo<input name="objective" maxlength="200" value="${e(c.objective||'')}" placeholder="Ex.: conseguir novos alunos"></label></div></div>${brandingFields({...c.brand_config,company_name:c.company_name||c.brand_config?.company_name})}<fieldset class="weekdays"><legend>Dias de publicação</legend>${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map((n,i)=>`<label><input type="checkbox" name="weekday" value="${i}" ${(c.weekdays||[0,1,2,3,4,5,6]).includes(i)?'checked':''}>${n}</label>`).join('')}</fieldset>`;}
function recoveryView(){const reset=state.authMode==='reset';return publicShell(`<section class="panel recovery-panel"><h1>${reset?'Defina sua nova senha':'Recuperar acesso'}</h1><p>${reset?'O link é de uso único e expira em 30 minutos.':'Se a conta existir, enviaremos instruções por e-mail.'}</p><form id="${reset?'reset-form':'forgot-form'}"><div class="field"><label>${reset?'Nova senha':'Seu e-mail'}<input name="${reset?'password':'email'}" type="${reset?'password':'email'}" ${reset?'minlength="10" maxlength="128" autocomplete="new-password"':'autocomplete="email" maxlength="254"'} required></label></div><p class="form-error" role="alert"></p><button class="btn btn-primary" type="submit">${reset?'Redefinir senha':'Enviar instruções'}</button></form><button class="btn-link mt-20" data-action="auth-login">Voltar para entrar</button></section>`);}
const saasForms=new Set(['profile-form','password-form','forgot-form','reset-form','delete-account-form','publish-form']);
document.addEventListener('submit',async event=>{const form=event.target;if(!(form instanceof HTMLFormElement)||!saasForms.has(form.getAttribute('id')))return;event.preventDefault();const id=form.getAttribute('id');if(form.dataset.busy)return;form.dataset.busy='true';const data=new FormData(form);const button=$('button[type=submit]',form);if(button)button.disabled=true;try{
 if(id==='profile-form'){await api('/api/account/profile',{method:'PUT',body:{name:data.get('name')}});state.session=await api('/api/session');render();toast('Perfil atualizado.');}
 if(id==='password-form'){await api('/api/account/password',{method:'POST',body:{current_password:data.get('current_password'),password:data.get('password')}});state.session=await api('/api/session');state.authMode='login';state.page='login';location.hash='login';render();toast('Senha alterada. Entre novamente.');}
 if(id==='forgot-form'){await api('/api/auth/forgot-password',{method:'POST',body:{email:data.get('email')}});toast('Se a conta existir, as instruções serão enviadas.');}
 if(id==='reset-form'){await api('/api/auth/reset-password',{method:'POST',body:{token:state.resetToken,password:data.get('password')}});state.resetToken=null;state.authMode='login';state.page='login';render();toast('Senha redefinida. Entre com sua nova senha.');}
 if(id==='delete-account-form'){await api('/api/account',{method:'DELETE',body:{password:data.get('password'),confirmed:data.get('confirmed')==='on'}});closeModal();state.session=await api('/api/session');state.page='overview';location.hash='overview';render();toast('Conta bloqueada; exclusão de arquivos solicitada.');}
 if(id==='publish-form'){await api(`/api/posts/${data.get('id')}/publish`,{method:'POST',body:{account_id:data.get('account_id'),confirmed:data.get('confirmed')==='on'}});closeModal();await refresh();toast('Publicação autorizada e enfileirada. Acompanhe o resultado.');}
 }catch(err){formError(form,err.message);}finally{delete form.dataset.busy;if(button)button.disabled=false;}});
document.addEventListener('click',async event=>{const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;const id=target.dataset.id;try{
 if(action==='cancel-checkout'){await api('/api/billing/checkout/cancel',{method:'POST'});await refresh();toast('Checkout pendente cancelado.');}
 if(action==='forgot-password'){state.authMode='forgot';state.page='login';location.hash='login';render();}
 if(action==='confirm-render-again'){await api(`/api/posts/${id}/render`,{method:'POST'});closeModal();await refresh();toast('Nova geração iniciada.');}
 if(action==='new-image')await videoEditor(null,'image');
 if(action==='verify-email'){await api('/api/account/verification',{method:'POST'});toast('E-mail de confirmação solicitado.');}
 if(action==='check-permissions'){const r=await api(`/api/accounts/${id}/permissions`,{method:'POST'});toast(r.ok?'Permissões de publicação confirmadas.':'Faltam permissões de publicação. Reconecte a conta e confira a revisão Meta.',!r.ok);}
 if(action==='delete-asset')confirmModal('Excluir imagem?','A imagem só pode ser removida se não estiver em uso por publicações ou campanhas.','confirm-delete-asset',id,true,'Excluir imagem');
 if(action==='confirm-delete-asset'){await api(`/api/assets/${id}`,{method:'DELETE'});closeModal();await refresh();toast('Exclusão solicitada.');}
 if(action==='delete-account')showModal('Solicitar exclusão da conta','Esta ação bloqueia seu acesso e solicita a limpeza dos seus dados.',`<div class="field"><label>Senha atual<input type="password" name="password" autocomplete="current-password" maxlength="128" required></label></div><label class="consent"><input type="checkbox" name="confirmed" required><span>Confirmo a exclusão da conta e o cancelamento da assinatura, quando aplicável.</span></label>`,`<button type="button" class="btn btn-secondary" data-action="close-modal">Cancelar</button><button type="submit" class="btn btn-danger">Solicitar exclusão</button>`,'delete-account-form');
 if(action==='publish-now')showModal('Autorizar publicação agora','O envio será processado pelo sistema e o resultado aparecerá no histórico.',`<input type="hidden" name="id" value="${e(id)}"><div class="field"><label>Conta do Instagram<select name="account_id" required>${accountOptions(null,false)}</select></label></div><label class="consent"><input type="checkbox" name="confirmed" required><span>Autorizo publicar este conteúdo agora na conta selecionada.</span></label>`,`<button type="button" class="btn btn-secondary" data-action="close-modal">Cancelar</button><button type="submit" class="btn btn-primary">Autorizar envio</button>`,'publish-form');
 }catch(err){toast(err.message,true);}});
document.addEventListener('change',async event=>{if(event.target.id!=='library-upload')return;const file=event.target.files?.[0];if(!file)return;const data=new FormData();data.append('file',file);try{await api('/api/assets',{method:'POST',body:data});await refresh();toast('Imagem enviada para sua biblioteca.');}catch(err){toast(err.message,true);}finally{event.target.value='';}});

function usagePanel(){const u=state.dashboard?.usage;if(!u)return '';return `<section class="panel usage-panel"><div><span class="eyebrow">SEU PLANO</span><h3>${e(u.plan==='free'?'Demonstração':u.plan.toUpperCase())}</h3><p>Status: ${e(u.status)}${u.renews_at?' · Até '+dateFmt(u.renews_at):''}</p></div><div><strong>${e(u.videos?.used??u.used)} / ${e(u.videos?.limit??u.limit)}</strong><p>Vídeos no período</p></div><div><strong>${e(u.images?.used??0)} / ${e(u.images?.limit??0)}</strong><p>Imagens no período</p></div><a class="btn btn-secondary" href="#settings">Gerenciar plano</a></section>`;}
